cypress_script:
describe('Links Page API Response Handling', () => {
  it('should navigate to the Created link and remain on the Links page', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('a#created').click();
    cy.url().should('eq', 'https://demoqa.com/links');
  });
  it('should navigate to the No Content link and remain on the Links page', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('a#no-content').click();
    cy.url().should('eq', 'https://demoqa.com/links');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Links Page API Response Handling', () => {
  test('should navigate to the Created link and remain on the Links page', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('a#created');
    await expect(page).toHaveURL('https://demoqa.com/links');
  });
  test('should navigate to the No Content link and remain on the Links page', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('a#no-content');
    await expect(page).toHaveURL('https://demoqa.com/links');
  });
});
